from calc1_volume_helpers import *
def shell(b,n,page,st,pieces,v,axis=0,setup=False,parts=[],extra=[],numeric=False):
 pieces=[tuple(map(s.sympify,p))for p in pieces];steps=list(extra);values=[];ints=[];plots=[]
 for lo,hi,up,dn,radius in pieces:
  height=s.simplify(up-dn);assert float(height.subs(v,(lo+hi)/2))>=0 and float(radius.subs(v,(lo+hi)/2))>=0
  expr=2*s.pi*radius*height;I=s.Integral(expr,(v,lo,hi));ints.append(I)
  steps+=fs(str(v)+r'\in['+tex(lo)+','+tex(hi)+r'],\quad r='+tex(radius)+r',\quad h='+tex(height),r'C=2\pi r='+tex(2*s.pi*radius)+r',\quad dV=2\pi rh\,d'+str(v))
  q=mp.quad(s.lambdify(v,expr,'mpmath'),[float(lo),float(hi)])
  if numeric:
   val=s.Float(str(q),30);q2=mp.quadgl(s.lambdify(v,expr,'mpmath'),[float(lo),float(hi)],maxdegree=10);assert abs(q-q2)<1e-7,(n,q,q2)
  else:val=s.integrate(s.expand(expr),(v,lo,hi));assert not val.has(s.Integral),(n,val);assert abs(float(val)-float(q))<1e-7*max(1,abs(float(q))),(n,val,q)
  values.append(val);steps+=fs(s.latex(I)+(''if setup else(r'\approx'if numeric else'=')+tex(val)))
  fu=s.lambdify(v,up,'math');fd=s.lambdify(v,dn,'math');mid=float((lo+hi)/2);a=float(axis)
  if str(v)=='x':
   top=lambda t,q,fu=fu:(a+(t-a)*math.cos(q),fu(t),(t-a)*math.sin(q));bot=lambda t,q,fd=fd:(a+(t-a)*math.cos(q),fd(t),(t-a)*math.sin(q));cyl=lambda u,q,fu=fu,fd=fd,mid=mid:(a+(mid-a)*math.cos(q),fd(mid)+u*(fu(mid)-fd(mid)),(mid-a)*math.sin(q));flat=lambda t,u,fu=fu,fd=fd:(t,fd(t)+u*(fu(t)-fd(t)),0)
  else:
   top=lambda t,q,fu=fu:(fu(t),a+(t-a)*math.cos(q),(t-a)*math.sin(q));bot=lambda t,q,fd=fd:(fd(t),a+(t-a)*math.cos(q),(t-a)*math.sin(q));cyl=lambda u,q,fu=fu,fd=fd,mid=mid:(fd(mid)+u*(fu(mid)-fd(mid)),a+(mid-a)*math.cos(q),(mid-a)*math.sin(q));flat=lambda t,u,fu=fu,fd=fd:(fd(t)+u*(fu(t)-fd(t)),t,0)
  plots.extend([(flat,(float(lo),float(hi)),(0,1),'Plane generating region'),([top,bot],(float(lo),float(hi)),(0,2*math.pi),f'{b.section}.{n}: solid boundary'),(cyl,(0,1),(0,2*math.pi),'Representative cylindrical shell')])
 V=s.simplify(sum(values));ans=M('V='+s.latex(s.Add(*ints,evaluate=False)))if setup else M((r'V\approx'+f'{float(V):.5f}')if numeric else'V='+tex(V))
 b.add(n,page,('원통껍질법','Cylindrical shells'),st,steps,same(ans),parts=parts);b.verify(n,'껍질 반지름·높이의 비음성과 회전 영역의 중복 여부를 확인하고 적분을 독립 수치구적으로 대조했다.','Checked nonnegative shell radii/heights and absence of double counting, then compared the integral with independent numerical quadrature.')
 b.plot(n,plots,('영역을 직접 회전해 만든 경계와 대표 원통껍질. 각 패널은 가독성을 위해 별도로 확대했다.','Boundary generated by rotating the region and a representative shell. Panels are scaled separately for readability.'))
 return V
